# Read template file
template_path = "devotional-template.html"
if not os.path.exists(template_path):
    print(f"Error: Template file '{template_path}' not found in current directory.")
    exit(1)

with open(template_path, "r", encoding="utf-8") as f:
    template_content = f.read()

# Output directory for October
output_dir = "2026October"
os.makedirs(output_dir, exist_ok=True)

# Generate individual HTML files
for entry in october_devotionals:
    day = entry["day"]
    title = entry["title"]
    
    # Body HTML paragraph construction
    body_html = "".join([f"<p>{p}</p>" for p in entry["body"]])
    
    # Navigation links: Day 1 bridges to September 30; Day 31 stops at '#'
    prev_link = "../2026September/day30.html" if day == 1 else f"day{day-1}.html"
    next_link = f"day{day+1}.html" if day < 31 else "#"
    
    # Client-side date guard script for October (month index 9)
    date_guard_script = f"""<script>
  (function() {{
    const nowLagos = new Date(new Date().toLocaleString('en-US', {{ timeZone: 'Africa/Lagos' }}));
    const currentYear = nowLagos.getFullYear();
    const currentMonth = nowLagos.getMonth(); // 9 = October
    const currentDay = nowLagos.getDate();

    const pageMonth = 9;
    const pageDay = {day};

    if (currentYear < 2026 || (currentYear === 2026 && (currentMonth < pageMonth || (currentMonth === pageMonth && currentDay < pageDay)))) {{
      alert("This devotional is not available yet. It will unlock on October {day}. Redirecting to today's reading.");
      window.location.href = "../index.html";
    }}
  }})();
</script>"""

    # Inject the date guard directly before </head>
    page_html = template_content.replace("</head>", f"{date_guard_script}\n</head>")
    
    # Replace template placeholders
    page_html = page_html.replace("{{MONTH}}", "October")
    page_html = page_html.replace("{{MONTH_UPPER}}", "OCTOBER")
    page_html = page_html.replace("{{DAY}}", str(day))
    page_html = page_html.replace("{{TITLE}}", title)
    page_html = page_html.replace("{{OPENING}}", entry["opening"])
    page_html = page_html.replace("{{BODY}}", body_html)
    page_html = page_html.replace("{{MEM_VERSE}}", entry["mv_text"])
    page_html = page_html.replace("{{MEM_REF}}", entry["mv_citation"])
    page_html = page_html.replace("{{PRAYER}}", entry["prayer"])
    page_html = page_html.replace("{{PREV_LINK}}", prev_link)
    page_html = page_html.replace("{{NEXT_LINK}}", next_link)

    file_name = f"day{day}.html"
    file_path = os.path.join(output_dir, file_name)
    
    with open(file_path, "w", encoding="utf-8") as f:
        f.write(page_html)

print(f"Successfully generated 31 guarded HTML pages in '{output_dir}/'.")